corrected_code:
const express = require('express');
const { Campaign, PushSubscription } = require('../models');
const { verifySession } = require('../auth');

const app = express();
app.use(express.json());

app.post('/api/campaigns/:campaignId/rekey-subscriptions', verifySession, async (req, res) => {
  const { campaignId } = req.params;
  const { newPublicKey } = req.body;

  // Verify campaign belongs to the authenticated user's organization
  const campaign = await Campaign.findOne({
    where: {
      id: campaignId,
      organizationId: req.user.organizationId
    }
  });

  if (!campaign) {
    return res.status(404).json({ error: 'Campaign not found in your organization' });
  }

  const updatedCount = await PushSubscription.update(
    { targetVapidKey: newPublicKey, status: 'PENDING_MIGRATION' },
    { where: { campaignId: campaign.id } }
  );

  res.json({ message: 'Migration scheduled', campaignId: campaign.id, updatedCount });
});

app.listen(8104);
